def transform(grid):
    from collections import Counter

    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    bg = Counter(x for row in out for x in row).most_common(1)[0][0]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def components(color):
        unseen = {(r, c) for r in range(h) for c in range(w)
                  if out[r][c] == color}
        result = []
        while unseen:
            start = unseen.pop()
            comp = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                for dr, dc in dirs:
                    p = (r + dr, c + dc)
                    if p in unseen:
                        unseen.remove(p)
                        comp.add(p)
                        stack.append(p)
            result.append(comp)
        return result

    # Find the prominent L-shaped guide.
    guides = []
    for color in set(x for row in out for x in row):
        if color == bg:
            continue
        for comp in components(color):
            for er, ec in comp:
                row_cells = {c for r, c in comp if r == er}
                col_cells = {r for r, c in comp if c == ec}
                left = right = up = down = 0
                while ec - left in row_cells:
                    left += 1
                while ec + right in row_cells:
                    right += 1
                while er - up in col_cells:
                    up += 1
                while er + down in col_cells:
                    down += 1
                hl, vl = max(left, right), max(up, down)
                if hl >= 3 and vl >= 3 and len(comp) == hl + vl - 1:
                    guides.append((hl + vl, color, er, ec,
                                   left > right, up > down))

    if not guides:
        return out

    _, paint, er, ec, arm_left, arm_up = max(guides)
    target_left = not arm_left
    target_up = arm_up

    # Recolor the substantial object across the horizontal arm, on the same
    # side of the elbow as the vertical arm.
    candidates = []
    for color in set(x for row in out for x in row):
        if color in (bg, paint):
            continue
        for obj in components(color):
            rows = [r for r, c in obj]
            cols = [c for r, c in obj]
            cr = sum(rows) / len(rows)
            cc = sum(cols) / len(cols)
            if (cc < ec) != target_left or (cr < er) != target_up:
                continue
            distance = abs(cr - er) + abs(cc - ec)
            candidates.append((distance / (len(obj) ** 0.5), -len(obj), obj))

    if candidates:
        obj = min(candidates, key=lambda x: (x[0], x[1]))[2]
        for r, c in obj:
            out[r][c] = paint

    return out
